299: func (s *ClientService) sendClientMessage(ctx context.Context, tx *sql.Tx, env *Envelope, principal string, sess *clientSessionRow) (*Response, error) {
300: 	p, err := clientPrincipal(ctx, tx, principal, sess.project, true)
301: 	if err != nil {
302: 		return clientFault(env, err)
303: 	}
304: 	var payload struct {
305: 		Text        string   `json:"text"`
306: 		Attachments []string `json:"attachment_artifact_ids"`
307: 		Delivery    string   `json:"delivery"`
308: 	}
309: 	if err = json.Unmarshal(env.Payload, &payload); err != nil {
310: 		return nil, err
311: 	}
312: 	if strings.TrimSpace(payload.Text) == "" || utf8.RuneCountInString(payload.Text) > 16384 {
313: 		return NewTypedRejection(env, "CONTENT_TOO_LARGE", "message must contain 1 to 16384 characters"), nil
314: 	}
315: 	var workspace, model string
316: 	var lease, previous sql.NullString
317: 	if err = tx.QueryRowContext(ctx, "SELECT workspace_ref,model_config_ref,lease_expires_at,task_id FROM client_sessions WHERE id=? AND project_id=?", sess.sessionID, sess.project).Scan(&workspace, &model, &lease, &previous); err != nil {
