321: 	if parseErr != nil || !expires.After(time.Now()) {
322: 		return NewTypedRejection(env, "LEASE_EXPIRED", "writer lease expired; acquire a current writer lease"), nil
323: 	}
324: 	if err = s.checkClientBinding(ctx, tx, principal, sess.project, workspace, model); err != nil {
325: 		return clientFault(env, err)
326: 	}
327: 	if previous.Valid {
328: 		task, err := load(tx, sess.project, "Task", previous.String)
329: 		if err != nil {
330: 			return nil, err
331: 		}
332: 		if payload.Delivery != "NORMAL" {
333: 			if err = s.SessionRuntime.AdmitTurn(ctx, tx, sess.project, model, task); err != nil {
334: 				return clientFault(env, err)
335: 			}
336: 			return s.enqueueClientMessage(ctx, tx, env, principal, sess, task, payload.Text, payload.Delivery, payload.Attachments)
337: 		}
338: 		if !clientTurnSettled(tx, sess.project, sess.sessionID, task) {
339: 			return NewTypedRejection(env, "SESSION_BUSY", "the previous turn requires settlement or explicit cancellation"), nil
340: 		}
341: 	}
342: 	if payload.Delivery != "NORMAL" {
343: 		return NewTypedRejection(env, "SESSION_BUSY", "an original task is required"), nil
344: 	}
345: 	refs := Empty()
346: 	seen := map[string]bool{}
347: 	for _, id := range payload.Attachments {
348: 		if seen[id] {
349: 			return NewTypedRejection(env, "INVALID_REQUEST", "duplicate attachment"), nil
350: 		}
351: 		seen[id] = true
352: 		a, err := s.Domain.readObject(tx, p, sess.project, "Artifact", id)
353: 		if err != nil {
354: 			return clientFault(env, err)
355: 		}
356: 		if err = s.Domain.effective(tx, sess.project, Ref(a, "Artifact")); err != nil {
357: 			return clientFault(env, err)
358: 		}
359: 		refs = append(refs, Ref(a, "Artifact"))
360: 	}
361: 	// Freeze every completed prior USER/ASSISTANT message before this turn's
362: 	// USER event exists. The bounded journal copy enters the new Task as a real
363: 	// sandbox artifact input; a first turn has no history ref.
