430: 		return bad()
431: 	}
432: 	for _, r := range u.Host {
433: 		if r > 127 {
434: 			return bad()
435: 		}
436: 	}
437: 	if strings.HasPrefix(u.Host, "[") {
438: 		end := strings.IndexByte(u.Host, ']')
439: 		if end < 0 || net.ParseIP(u.Host[1:end]) == nil {
440: 			return bad()
441: 		}
442: 		if end+1 < len(u.Host) && u.Host[end+1] != ':' {
443: 			return bad()
444: 		}
445: 	} else if strings.Count(u.Host, ":") > 1 || strings.ContainsAny(u.Host, "[]") {
446: 		return bad()
447: 	}
448: 	port := u.Port()
449: 	if strings.HasSuffix(u.Host, ":") {
450: 		return bad()
451: 	}
452: 	if port != "" {
453: 		for _, r := range port {
454: 			if r < '0' || r > '9' {
