458: 		n, e := strconv.Atoi(port)
459: 		if e != nil || n < 1 || n > 65535 {
460: 			return bad()
461: 		}
462: 	}
463: 	if strings.Contains(u.Path, "//") {
464: 		return bad()
465: 	}
466: 	for _, segment := range strings.Split(u.Path, "/") {
467: 		if segment == "." || segment == ".." {
468: 			return bad()
469: 		}
470: 	}
471: 	if strings.HasSuffix(strings.ToLower(strings.TrimSuffix(u.Path, "/")), "/chat/completions") {
472: 		return bad()
